FILE: app/src/fade-in.ts
```ts
import { createPropertyAnimationClip, createPropertyAnimationGroup } from "@babylonjs/lite";
import type { AnimationManager, AnimationGroup } from "@babylonjs/lite";

export function fadeIn(manager: AnimationManager, panel: { alpha: number }, durationMs: number): AnimationGroup {
    const durationSec = durationMs / 1000;

    const clip = createPropertyAnimationClip("fadeIn", [
        {
            path: "alpha",
            keys: [
                { time: 0, value: 0 },
                { time: durationSec, value: 1 },
            ],
            interpolation: "linear",
        },
    ]);

    return createPropertyAnimationGroup(manager, panel, clip, {
        loop: false,
        fromTime: 0,
        toTime: durationSec,
    });
}
```

I created `src/fade-in.ts` which builds a two-key linear property-animation clip on the `alpha` path (0 → 1 over `durationMs`/1000 seconds) and hands it to `createPropertyAnimationGroup` with `loop: false`, so the group starts playing immediately on the manager, writes a steady ramp, and stops at 1 with `isPlaying` false once `toTime` is reached. I was not sure whether `durationMs` could ever be 0 (which would make `toTime === fromTime` and throw per note 14), but I assumed the caller guarantees a positive duration.
